$semesterTypeStmt=$pdo->prepare('SELECT semester_no FROM semesters WHERE id=:semester_id LIMIT 1'); $semesterTypeStmt->execute(['semester_id'=>$selectedSemesterId]); $selectedSemesterNo=(int)($semesterTypeStmt->fetchColumn()?:0);
