<div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-100 bg-slate-50/70 px-5 py-4 text-sm text-slate-600">Forms are drafts until you explicitly start one. Starting a form automatically stops every other form, so supervisors can access only one evaluation at a time.</div><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-4">Form Title</th><th class="px-5 py-4">School Year</th><th class="px-5 py-4">Semester</th><th class="px-5 py-4">Status</th><th class="px-5 py-4">Created Date</th><th class="px-5 py-4">Actions</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($forms as $entry): ?><tr><td class="px-5 py-4 font-semibold text-slate-900"><?= $safe($entry['title']) ?></td><td class="px-5 py-4"><?= $safe($entry['year_label']) ?></td><td class="px-5 py-4"><?= $safe($entry['semester_name']) ?></td><td class="px-5 py-4"><span class="rounded-full px-3 py-1 text-xs font-semibold <?= $entry['is_active']?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-600' ?>"><?= $entry['is_active']?'Running':'Draft' ?></span></td><td class="px-5 py-4 text-slate-600"><?= $safe(date('M j, Y',strtotime((string)$entry['created_at']))) ?></td><td class="px-5 py-4"><div class="flex flex-wrap items-center gap-2"><?php $url=appUrl('head_teacher/evaluation_management.php'); ?><a class="action-link" href="<?= $safe($url.'?view='.(int)$entry['id']) ?>">View</a><a class="action-link" href="<?= $safe($url.'?edit='.(int)$entry['id']) ?>">Edit</a><form method="post" class="inline"><input type="hidden" name="evaluation_action" value="duplicate"><input type="hidden" name="form_id" value="<?= (int)$entry['id'] ?>"><button class="action-link" type="submit">Duplicate</button></form><?php if($entry['is_active']): ?><form method="post" class="inline" onsubmit="return confirm('Stop this evaluation? Supervisors will no longer be able to evaluate students with this form.')"><input type="hidden" name="evaluation_action" value="stop"><input type="hidden" name="form_id" value="<?= (int)$entry['id'] ?>"><button class="rounded-lg border border-amber-300 px-2.5 py-1.5 text-xs font-bold text-amber-700" type="submit">Stop Evaluation</button></form><?php else: ?><form method="post" class="inline" onsubmit="return confirm('Start this evaluation now? Any currently running evaluation will be stopped.')"><input type="hidden" name="evaluation_action" value="start"><input type="hidden" name="form_id" value="<?= (int)$entry['id'] ?>"><button class="rounded-lg bg-emerald-700 px-2.5 py-1.5 text-xs font-bold text-white hover:bg-emerald-800" type="submit">Start Evaluation Now</button></form><form method="post" class="inline" onsubmit="return confirm('Delete this draft form?')"><input type="hidden" name="evaluation_action" value="delete"><input type="hidden" name="form_id" value="<?= (int)$entry['id'] ?>"><button class="action-link text-rose-700" type="submit">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$forms): ?><tr><td colspan="6" class="px-5 py-12 text-center text-slate-500">No evaluation forms yet. Create your first dynamic form.</td></tr><?php endif; ?></tbody></table></div></div>
<?php endif; ?>
