 rounded-xl border border-slate-300 bg-white px-4 py-3 text-sm text-slate-900 shadow-sm transition placeholder:text-slate-400 focus:border-emerald-600 focus:outline-none focus:ring-4 focus:ring-emerald-100" placeholder="e.g., juan@company.com" autocomplete="email"></label><label class="block"><span class="mb-2 block text-sm font-semibold text-slate-800">Partnered school or organization</span><input required name="partnered_school" class="w-full rounded-xl border border-slate-300 bg-white px-4 py-3 text-sm text-slate-900 shadow-sm transition placeholder:text-slate-400 focus:border-emerald-600 focus:outline-none focus:ring-4 focus:ring-emerald-100" placeholder="e.g., ABC Company"></label><div class="flex flex-col-reverse gap-3 pt-2 sm:flex-row sm:justify-end"><button type="button" id="cancelSupervisorModal" class="rounded-xl border border-slate-300 px-5 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Cancel</button><button class="rounded-xl bg-emerald-700 px-5 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-800 focus:outline-none focus:ring-4 focus:ring-emerald-200" type="submit">Create supervisor account</button></div></form></div></div>
