$script=<<<'JS'
const supervisorModal=document.getElementById('supervisorModal');const openSupervisorModal=document.getElementById('openSupervisorModal');if(openSupervisorModal){const closeSupervisorModal=()=>{supervisorModal.classList.add('hidden');supervisorModal.classList.remove('flex')};openSupervisorModal.onclick=()=>{supervisorModal.classList.remove('hidden');supervisorModal.classList.add('flex');supervisorModal.querySelector('input[name="supervisor_name"]').focus()};document.getElementById('closeSupervisorModal').onclick=closeSupervisorModal;document.getElementById('cancelSupervisorModal').onclick=closeSupervisorModal;supervisorModal.addEventListener('click',event=>{if(event.target===supervisorModal)closeSupervisorModal()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!supervisorModal.classList.contains('hidden'))closeSupervisorModal()})}
const builder=document.getElementById('evaluationBuilder');
if(builder){let sectionNo=document.querySelectorAll('.section-card').length,commentNo=document.querySelectorAll('.comment-row').length;
const remove=e=>{if(e.target.classList.contains('remove-row'))e.target.closest('.rating-row,.section-card,.question-row,.comment-row').remove()};builder.addEventListener('click',remove);
document.querySelector('.add-comment').onclick=()=>{document.getElementById('comments').insertAdjacentHTML('beforeend',`<div class="comment-row grid gap-2 md:grid-cols-[1fr_1fr_auto_auto_auto]"><input name="comments[${commentNo}][title]" class="input" placeholder="Comment title"><input name="comments[${commentNo}][placeholder]" class="input" placeholder="Placeholder"><label class="flex items-center gap-1 text-xs"><input type="checkbox" name="comments[${commentNo}][required]" value="1"> Required</label><label class="flex items-center gap-1 text-xs"><input type="checkbox" name="comments[${commentNo}][enabled]" value="1" checked> Enabled</label><button type="button" class="remove-row btn-danger">Delete</button></div>`);commentNo++};
const bindSection=card=>{card.querySelector('.add-question').onclick=()=>{let box=card.querySelector('.questions'),n=box.querySelectorAll('.question-row').length,s=card.querySelector('input[name*="[title]"]').name.match(/sections\[(\d+)\]/)[1];box.insertAdjacentHTML('beforeend',`<div class="question-row flex gap-2"><span class="pt-2 text-sm text-slate-500">Q</span><input name="sections[${s}][questions][${n}][text]" class="input" placeholder="Question text" required><label class="flex shrink-0 items-center gap-1 text-xs"><input type="checkbox" name="sections[${s}][questions][${n}][required]" value="1" checked> Required</label><button type="button" class="remove-row btn-danger">Delete</button></div>`)};};document.querySelectorAll('.section-card').forEach(bindSection);
document.querySelector('.add-section').onclick=()=>{let s=sectionNo++;document.getElementById('sections').insertAdjacentHTML('beforeend',`<div class="section-card rounded-xl border border-slate-200 bg-slate-50 p-4"><div class="flex gap-2"><input name="sections[${s}][title]" class="input" placeholder="Section title" required><button type="button" class="remove-row btn-danger">Delete</button></div><div class="questions mt-3 space-y-2"><div class="question-row flex gap-2"><span class="pt-2 text-sm text-slate-500">Q</span><input name="sections[${s}][questions][0][text]" class="input" placeholder="Question text" required><label class="flex shrink-0 items-center gap-1 text-xs"><input type="checkbox" name="sections[${s}][questions][0][required]" value="1" checked> Required</label><button type="button" class="remove-row btn-danger">Delete</button></div></div><button type="button" class="add-question mt-3 btn-secondary">+ Add Question</button></div>`);bindSection(document.querySelectorAll('.section-card')[document.querySelectorAll('.section-card').length-1])};
document.getElementById('previewBuilder').onclick=()=>{const w=window.open('','evaluationPreview','width=900,height=800'),high=parseInt(document.querySelector('[name=rating_highest]').value,10),low=parseInt(document.querySelector('[name=rating_lowest]').value,10),scale=Number.isFinite(high)&&Number.isFinite(low)&&high>=low?Array.from({length:high-low+1},(_,i)=>{const value=high-i;return value+(i===0?' - Excellent':(value===low?' - Below Average':''))}).join(' &nbsp; ○ '):'Enter a valid rating range';w.document.write('<title>Evaluation Preview</title><style>body{font:14px Arial;padding:40px;max-width:800px;margin:auto}h1{font-size:24px}h2{border-bottom:1px solid #bbb;padding-bottom:6px;margin-top:28px}.q{margin:16px 0}.rating{color:#475569;margin-top:6px}</style><p>PHINMA - CAGAYAN DE ORO COLLEGE</p><h1>'+document.querySelector('[name=title]').value+'</h1><pre style="white-space:pre-wrap;background:#f8fafc;padding:16px">'+document.querySelector('[name=instructions]').value+'</pre>');document.querySelectorAll('.section-card').forEach(s=>{w.document.write('<h2>'+s.querySelector('input[name*="[title]"]').value+'</h2>');s.querySelectorAll('.question-row input[type=text]').forEach((q,n)=>w.document.write('<div class="q">'+(n+1)+'. '+q.value+'<div class="rating">'+scale+'</div></div>'))});w.document.write('<h2>Comments</h2>');document.querySelectorAll('.comment-row').forEach(c=>w.document.write('<p><b>'+c.querySelector('input').value+'</b><br>________________________________________</p>'));w.document.write('</body></html>');w.document.close()};}
JS;
$script = '<script>' . $script . '</script>';
$script .= '<script>const activePartneredSchools=' . json_encode(array_values($partneredSchools), JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) . ';const schoolInput=document.querySelector("#supervisorModal input[name=partnered_school]");if(schoolInput){const schoolSelect=document.createElement("select");schoolSelect.name="partnered_school";schoolSelect.required=true;schoolSelect.className=schoolInput.className;const placeholder=document.createElement("option");placeholder.value="";placeholder.textContent=activePartneredSchools.length?"Select an active partnered school":"No active partnered schools available";placeholder.disabled=true;placeholder.selected=true;schoolSelect.appendChild(placeholder);activePartneredSchools.forEach(name=>{const option=document.createElement("option");option.value=name;option.textContent=name;schoolSelect.appendChild(option)});schoolInput.replaceWith(schoolSelect)}</script>';
renderHeadTeacherPortalEnd($script);
